const ChoreRotationBoard = (props) => {
  const {
    weekStartDate,
    matrix = [],
    rulesSummary = '',
    fairnessScore,
    upcomingHighlights = []
  } = props;

  const formattedDate = (() => {
    if (!weekStartDate) return 'No start date';
    const d = new Date(weekStartDate);
    return isNaN(d.getTime()) ? String(weekStartDate) : d.toLocaleDateString();
  })();

  const safeFairness = (() => {
    const n = Number(fairnessScore);
    return isNaN(n) ? null : n;
  })();

  const fairnessBadge = (() => {
    if (safeFairness === null) {
      return (
        <span className="px-2 py-1 text-xs font-medium bg-gray-100 text-gray-700 rounded">
          Unknown
        </span>
      );
    }
    if (safeFairness >= 80) {
      return (
        <span className="px-2 py-1 text-xs font-medium bg-green-100 text-green-700 rounded">
          Excellent
        </span>
      );
    }
    if (safeFairness >= 60) {
      return (
        <span className="px-2 py-1 text-xs font-medium bg-blue-100 text-blue-700 rounded">
          Good
        </span>
      );
    }
    return (
      <span className="px-2 py-1 text-xs font-medium bg-gray-100 text-gray-700 rounded">
        Needs Balance
      </span>
    );
  })();

  const parsedMatrix = React.useMemo(() => {
    if (!Array.isArray(matrix) || matrix.length === 0) return [];
    const detectDelimiter = (line) => {
      if (line.indexOf('|') !== -1) return '|';
      if (line.indexOf(',') !== -1) return ',';
      if (line.indexOf('\t') !== -1) return '\t';
      return null;
    };
    const delimiter = detectDelimiter(matrix[0]);
    if (!delimiter) {
      return matrix.map((line) => [String(line)]);
    }
    return matrix.map((line) => line.split(delimiter).map((c) => c.trim()));
  }, [matrix]);

  const maxCols = React.useMemo(() => {
    if (!Array.isArray(parsedMatrix) || parsedMatrix.length === 0) return 0;
    return parsedMatrix.reduce((m, row) => Math.max(m, Array.isArray(row) ? row.length : 0), 0);
  }, [parsedMatrix]);

  const progressBar = (() => {
    if (safeFairness === null) {
      return (
        <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
          <div className="h-full w-0 bg-gray-300" />
        </div>
      );
    }
    const clamped = Math.max(0, Math.min(100, safeFairness));
    const barColor =
      clamped >= 80 ? 'bg-green-500' : clamped >= 60 ? 'bg-blue-500' : 'bg-gray-400';
    return (
      <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
        <div
          className={`h-full ${barColor}`}
          style={{ width: clamped + '%' }}
        />
      </div>
    );
  })();

  return (
    <div className="w-full max-w-2xl mx-auto bg-white rounded-lg shadow-sm border border-gray-200 p-6 hover:shadow-md transition-shadow duration-200 relative">
      <div className="flex items-start justify-between mb-4">
        <div>
          <h3 className="text-lg font-semibold text-gray-900">Chore Rotation Board</h3>
          <div className="text-sm text-gray-600 mt-1">Week starting: {formattedDate}</div>
        </div>
        <div className="text-right">
          <div className="text-sm font-medium text-gray-700">Fairness Score</div>
          <div className="flex items-center gap-2 mt-1">
            <div className="text-lg font-semibold text-gray-900">
              {safeFairness === null ? '—' : safeFairness.toFixed(0) + '%'}
            </div>
            {fairnessBadge}
          </div>
          <div className="mt-2">{progressBar}</div>
        </div>
      </div>

      <div className="mb-5">
        <div className="text-sm font-medium text-gray-700 mb-2">Rotation Matrix</div>
        {Array.isArray(parsedMatrix) && parsedMatrix.length > 0 ? (
          <div className="overflow-x-auto rounded-md border border-gray-200">
            <table className="min-w-full divide-y divide-gray-200">
              <tbody className="bg-white divide-y divide-gray-200">
                {parsedMatrix.map((row, rIdx) => (
                  <tr key={'row-' + rIdx} className={rIdx === 0 && maxCols > 1 ? 'bg-gray-50' : ''}>
                    {Array.from({ length: maxCols }).map((_, cIdx) => {
                      const cell = Array.isArray(row) ? row[cIdx] : '';
                      const isHeader = rIdx === 0 && maxCols > 1;
                      return isHeader ? (
                        <th
                          key={'cell-' + rIdx + '-' + cIdx}
                          className="px-4 py-2 text-left text-xs font-medium text-gray-700 uppercase tracking-wider"
                        >
                          {cell || ''}
                        </th>
                      ) : (
                        <td
                          key={'cell-' + rIdx + '-' + cIdx}
                          className="px-4 py-2 text-sm text-gray-700 align-top"
                        >
                          {cell || ''}
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="p-4 bg-gray-50 border border-dashed border-gray-300 rounded-md text-sm text-gray-600">
            No rotation data to display
          </div>
        )}
      </div>

      <div className="mb-5">
        <div className="text-sm font-medium text-gray-700 mb-2">Rules Summary</div>
        {rulesSummary ? (
          <p className="text-sm text-gray-700 leading-relaxed whitespace-pre-line">
            {rulesSummary}
          </p>
        ) : (
          <div className="p-4 bg-gray-50 border border-dashed border-gray-300 rounded-md text-sm text-gray-600">
            No rules provided
          </div>
        )}
      </div>

      <div>
        <div className="flex items-center justify-between mb-2">
          <div className="text-sm font-medium text-gray-700">Upcoming Highlights</div>
          <span className="text-xs text-gray-500">
            {Array.isArray(upcomingHighlights) ? upcomingHighlights.length : 0} items
          </span>
        </div>
        {Array.isArray(upcomingHighlights) && upcomingHighlights.length > 0 ? (
          <div className="space-y-2">
            {upcomingHighlights.map((item, idx) => (
              <div key={'hl-' + idx} className="p-3 bg-gray-50 rounded-md border border-gray-200">
                <div className="flex items-start gap-2">
                  <span className="text-green-600">•</span>
                  <p className="text-sm text-gray-700 line-clamp-3">{String(item)}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="p-4 bg-gray-50 border border-dashed border-gray-300 rounded-md text-sm text-gray-600">
            No upcoming highlights
          </div>
        )}
      </div>
    </div>
  );
};

const RotationRulesPanel = (props) => {
  const {
    strategy,
    maxConsecutive,
    lockInDays,
    effortBalanceTarget,
    effectiveWeekStart
  } = props || {};

  const safeNumber = (n) => {
    const num = Number(n);
    return isNaN(num) ? null : num;
  };

  const formatNumber = (n, decimals) => {
    const num = safeNumber(n);
    if (num === null) return '—';
    if (typeof decimals === 'number') return num.toFixed(decimals);
    return num.toString();
  };

  const formatWeekStart = (value) => {
    if (!value) return '—';
    const isLikelyDate = typeof value === 'string' && (value.includes('-') || value.includes('/') || value.length > 10);
    if (isLikelyDate) {
      const d = new Date(value);
      return isNaN(d.getTime()) ? value : d.toLocaleDateString();
    }
    return value;
  };

  const strategyLabel = strategy === 'weighted' ? 'Weighted' : strategy === 'round_robin' ? 'Round Robin' : 'Unknown';
  const strategyBadgeClasses = strategy === 'weighted'
    ? 'bg-blue-100 text-blue-700'
    : strategy === 'round_robin'
      ? 'bg-green-100 text-green-700'
      : 'bg-gray-100 text-gray-700';

  const maxConsecVal = safeNumber(maxConsecutive);
  const lockInVal = safeNumber(lockInDays);
  const balanceTargetVal = safeNumber(effortBalanceTarget);

  const consistencyHint = (() => {
    if (maxConsecVal === null || lockInVal === null) return '—';
    if (maxConsecVal <= 1 && lockInVal <= 1) return 'High rotation frequency';
    if (maxConsecVal <= 2 && lockInVal <= 3) return 'Balanced cadence';
    if (maxConsecVal >= 4 || lockInVal >= 7) return 'Longer assignment windows';
    return 'Moderate cadence';
  })();

  const balanceHint = (() => {
    if (balanceTargetVal === null) return '—';
    if (balanceTargetVal <= 10) return 'Strict balance';
    if (balanceTargetVal <= 25) return 'Balanced with tolerance';
    if (balanceTargetVal <= 50) return 'Loose balance';
    return 'Very permissive';
  })();

  const weekStartDisplay = formatWeekStart(effectiveWeekStart);

  const hasAllRequired =
    typeof strategy === 'string' &&
    maxConsecVal !== null &&
    lockInVal !== null &&
    balanceTargetVal !== null &&
    typeof effectiveWeekStart === 'string';

  return (
    <div className="w-full max-w-2xl mx-auto bg-white rounded-lg shadow-lg p-6 border border-gray-200 hover:shadow-md transition-shadow">
      <div className="flex items-start justify-between">
        <div>
          <h3 className="text-lg font-semibold text-gray-900">Rotation Rules</h3>
          <p className="text-sm text-gray-500 mt-1">
            Overview of assignment rotation configuration
          </p>
        </div>
        <span className={`px-2 py-1 text-xs font-medium rounded ${strategyBadgeClasses}`}>
          {strategyLabel}
        </span>
      </div>

      {!hasAllRequired && (
        <div className="mt-4 p-3 rounded-md border border-yellow-200 bg-yellow-50 text-yellow-800 text-sm">
          Some configuration values are missing or invalid. Displaying available information.
        </div>
      )}

      <div className="mt-5 grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="p-4 bg-gray-50 rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-medium text-gray-700">Max Consecutive Assignments</span>
            <span className="px-2 py-0.5 text-xs bg-gray-100 text-gray-700 rounded">limit</span>
          </div>
          <div className="text-2xl font-semibold text-gray-900">
            {formatNumber(maxConsecutive, 0)}
          </div>
          <div className="text-xs text-gray-500 mt-1">
            Caps how many rounds one person can be assigned in a row
          </div>
        </div>

        <div className="p-4 bg-gray-50 rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-medium text-gray-700">Lock-in Period</span>
            <span className="px-2 py-0.5 text-xs bg-gray-100 text-gray-700 rounded">days</span>
          </div>
          <div className="text-2xl font-semibold text-gray-900">
            {formatNumber(lockInDays, 0)}
          </div>
          <div className="text-xs text-gray-500 mt-1">
            Minimum days before a newly assigned user can be rotated out
          </div>
        </div>

        <div className="p-4 bg-gray-50 rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-medium text-gray-700">Effort Balance Target</span>
            <span className="px-2 py-0.5 text-xs bg-green-100 text-green-700 rounded">balance</span>
          </div>
          <div className="text-2xl font-semibold text-gray-900">
            {balanceTargetVal !== null ? `${formatNumber(effortBalanceTarget, 0)}%` : '—'}
          </div>
          <div className="text-xs text-gray-500 mt-1">
            Target variance for distributing workload across team members
          </div>
        </div>

        <div className="p-4 bg-gray-50 rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-medium text-gray-700">Effective Week Start</span>
            <span className="px-2 py-0.5 text-xs bg-gray-100 text-gray-700 rounded">schedule</span>
          </div>
          <div className="text-2xl font-semibold text-gray-900">
            {weekStartDisplay}
          </div>
          <div className="text-xs text-gray-500 mt-1">
            The day the rotation calendar resets
          </div>
        </div>
      </div>

      <div className="mt-6 grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="p-4 bg-white rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-medium text-gray-700">Cadence Insight</span>
            <span className="px-2 py-0.5 text-xs bg-blue-100 text-blue-700 rounded">info</span>
          </div>
          <div className="text-sm text-gray-800">
            {consistencyHint}
          </div>
          <div className="text-xs text-gray-500 mt-1">
            Based on maxConsecutive and lockInDays
          </div>
        </div>

        <div className="p-4 bg-white rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-medium text-gray-700">Balance Insight</span>
            <span className="px-2 py-0.5 text-xs bg-green-100 text-green-700 rounded">insight</span>
          </div>
          <div className="text-sm text-gray-800">
            {balanceHint}
          </div>
          <div className="text-xs text-gray-500 mt-1">
            Interpreted from the effort balance target
          </div>
        </div>
      </div>

      <div className="mt-6 p-4 bg-gray-50 rounded-lg border border-gray-200">
        <div className="flex items-center mb-2">
          <span className="text-lg mr-2">🧭</span>
          <span className="text-sm font-medium text-gray-700">Strategy Details</span>
        </div>
        <p className="text-sm text-gray-600">
          {strategy === 'weighted'
            ? 'Weighted strategy favors members based on configured weights, improving fairness with nuanced distribution.'
            : strategy === 'round_robin'
              ? 'Round-robin strategy cycles evenly through members, providing straightforward and predictable rotation.'
              : 'Strategy information is unavailable.'}
        </p>
      </div>
    </div>
  );
};

const ChoreMatrix = (props) => {
  const { period, weekDates = [], roommates = [], assignments = [], fairnessScore } = props;

  const titleText = period || 'Schedule';
  const startDate = Array.isArray(weekDates) && weekDates.length > 0 ? new Date(weekDates[0]) : null;
  const endDate = Array.isArray(weekDates) && weekDates.length > 0 ? new Date(weekDates[weekDates.length - 1]) : null;

  const dateRangeText = startDate && endDate
    ? startDate.toLocaleDateString() + ' - ' + endDate.toLocaleDateString()
    : 'No dates';

  const rows = Array.isArray(roommates) ? roommates.length : 0;
  const cols = Array.isArray(weekDates) ? weekDates.length : 0;

  const matrix = React.useMemo(() => {
    const m = [];
    for (let r = 0; r < rows; r++) {
      const row = [];
      for (let c = 0; c < cols; c++) {
        const idx = r * cols + c;
        const val = Array.isArray(assignments) && idx < assignments.length ? assignments[idx] : '';
        row.push(typeof val === 'string' ? val : '');
      }
      m.push(row);
    }
    return m;
  }, [rows, cols, assignments]);

  const loadPerRoommate = React.useMemo(() => {
    if (!rows || !cols) return [];
    return matrix.map((row) => {
      const count = row.reduce((acc, v) => {
        const trimmed = (v || '').trim();
        return acc + (trimmed.length > 0 ? 1 : 0);
      }, 0);
      return count;
    });
  }, [matrix, rows, cols]);

  const totalAssigned = React.useMemo(() => {
    return loadPerRoommate.reduce((a, b) => a + b, 0);
  }, [loadPerRoommate]);

  const fairnessValue = typeof fairnessScore === 'number' && !isNaN(fairnessScore) ? fairnessScore : null;
  const fairnessLabel = fairnessValue === null ? 'N/A' : fairnessValue.toFixed(2);
  const fairnessToneClass =
    fairnessValue === null
      ? 'bg-gray-100 text-gray-700'
      : fairnessValue >= 0.8
      ? 'bg-green-100 text-green-700'
      : fairnessValue >= 0.5
      ? 'bg-blue-100 text-blue-700'
      : 'bg-gray-100 text-gray-700';

  const hasContent = rows > 0 && cols > 0;

  return (
    <div className="w-full max-w-2xl mx-auto bg-white border border-gray-200 rounded-lg shadow-sm p-4 hover:shadow-md transition-shadow duration-200">
      <div className="flex items-start justify-between mb-3">
        <div>
          <h3 className="text-lg font-semibold text-gray-900">{titleText}</h3>
          <div className="text-sm text-gray-600">{dateRangeText}</div>
        </div>
        <div className="text-right">
          <div className="text-sm text-gray-700">Fairness</div>
          <span className={'inline-block mt-1 px-2 py-1 text-xs font-medium rounded ' + fairnessToneClass}>
            {fairnessLabel}
          </span>
        </div>
      </div>

      {!hasContent ? (
        <div className="p-6 bg-gray-50 rounded-md border border-dashed border-gray-200 text-center">
          <div className="text-2xl mb-2">🧹</div>
          <div className="text-sm text-gray-700 mb-1">No chore matrix to display</div>
          <div className="text-xs text-gray-500">
            {rows === 0 && cols === 0
              ? 'Add roommates and dates to see the schedule.'
              : rows === 0
              ? 'No roommates provided.'
              : 'No dates provided.'}
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-3 py-2 text-left text-xs font-medium text-gray-700 uppercase tracking-wider w-40">
                    Roommate
                  </th>
                  {weekDates.map((d, i) => {
                    const dt = new Date(d);
                    const label = isNaN(dt.getTime()) ? d : dt.toLocaleDateString();
                    return (
                      <th key={i} className="px-3 py-2 text-left text-xs font-medium text-gray-700 uppercase tracking-wider">
                        {label}
                      </th>
                    );
                  })}
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-100">
                {roommates.map((name, r) => (
                  <tr key={r} className="hover:bg-gray-50 transition-colors">
                    <td className="px-3 py-2 whitespace-nowrap">
                      <div className="flex items-center">
                        <div className="h-8 w-8 rounded-full bg-blue-50 text-blue-700 flex items-center justify-center mr-2 text-xs font-semibold">
                          {typeof name === 'string' && name.trim().length > 0 ? name.trim()[0].toUpperCase() : '?'}
                        </div>
                        <div className="text-sm text-gray-900 font-medium">{name || 'Unnamed'}</div>
                      </div>
                    </td>
                    {matrix[r].map((cell, c) => {
                      const filled = (cell || '').trim().length > 0;
                      return (
                        <td key={c} className="px-3 py-2 align-top">
                          <div
                            className={
                              'p-2 rounded-md border text-sm ' +
                              (filled ? 'bg-blue-50 border-blue-200 text-gray-900' : 'bg-gray-50 border-gray-200 text-gray-500')
                            }
                          >
                            <div className="flex items-start justify-between">
                              <span className="font-medium">{filled ? cell : 'No assignment'}</span>
                            </div>
                          </div>
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <div className="p-3 bg-white rounded-md border border-gray-200">
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium text-gray-700">Roommates</span>
                <span className="px-2 py-0.5 text-xs rounded bg-gray-100 text-gray-700">{rows}</span>
              </div>
              <div className="text-lg font-semibold text-gray-900 mt-1">{rows.toLocaleString()}</div>
            </div>
            <div className="p-3 bg-white rounded-md border border-gray-200">
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium text-gray-700">Days</span>
                <span className="px-2 py-0.5 text-xs rounded bg-gray-100 text-gray-700">{cols}</span>
              </div>
              <div className="text-lg font-semibold text-gray-900 mt-1">{cols.toLocaleString()}</div>
            </div>
            <div className="p-3 bg-white rounded-md border border-gray-200">
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium text-gray-700">Total Assignments</span>
                <span className="px-2 py-0.5 text-xs rounded bg-gray-100 text-gray-700">
                  {rows * cols}
                </span>
              </div>
              <div className="text-lg font-semibold text-gray-900 mt-1">
                {totalAssigned.toLocaleString()}
              </div>
            </div>
          </div>

          {rows > 0 && (
            <div className="p-3 bg-gray-50 rounded-md border border-gray-200">
              <div className="text-sm font-medium text-gray-800 mb-2">Workload by roommate</div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                {roommates.map((name, i) => {
                  const count = loadPerRoommate[i] || 0;
                  const ratio = cols > 0 ? Math.min(1, count / cols) : 0;
                  const barWidth = Math.round(ratio * 100);
                  const barColor =
                    ratio >= 0.8 ? 'bg-green-500' : ratio >= 0.5 ? 'bg-blue-500' : 'bg-gray-400';
                  return (
                    <div key={i} className="bg-white rounded-md border border-gray-200 p-2">
                      <div className="flex items-center justify-between mb-1">
                        <span className="text-sm text-gray-700 line-clamp-1">{name || 'Unnamed'}</span>
                        <span className="text-xs text-gray-600">
                          {count}/{cols}
                        </span>
                      </div>
                      <div className="w-full h-2 bg-gray-100 rounded">
                        <div
                          className={'h-2 rounded ' + barColor}
                          style={{ width: barWidth + '%' }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          <div className="flex items-center justify-between text-xs text-gray-500">
            <div className="flex items-center space-x-3">
              <span className="inline-flex items-center">
                <span className="w-3 h-3 rounded mr-1.5 inline-block bg-blue-200 border border-blue-300" />
                Assigned
              </span>
              <span className="inline-flex items-center">
                <span className="w-3 h-3 rounded mr-1.5 inline-block bg-gray-200 border border-gray-300" />
                Unassigned
              </span>
            </div>
            <div className="text-gray-400">
              {typeof period === 'string' && period ? period : 'Period unspecified'}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const UpcomingAssignmentsList = (props) => {
  const {
    entries,
    periodLabel,
    maxItems,
    iconUrl,
    updatedAt
  } = props;

  const safeEntries = Array.isArray(entries) ? entries : [];
  const limit = typeof maxItems === 'number' && !isNaN(maxItems) && maxItems > 0 ? Math.floor(maxItems) : safeEntries.length;
  const displayed = safeEntries.slice(0, limit);
  const remaining = safeEntries.length - displayed.length;

  const titleLabel = periodLabel || 'Upcoming Assignments';

  let updatedLabel = '';
  if (updatedAt) {
    const d = new Date(updatedAt);
    updatedLabel = isNaN(d.getTime()) ? '' : d.toLocaleString();
  }

  return (
    <div className="w-full max-w-xl mx-auto bg-white rounded-lg shadow-sm border border-gray-200 p-4 hover:shadow-md transition-shadow">
      <div className="flex items-start gap-3 mb-3">
        <div className="flex-shrink-0">
          {iconUrl ? (
            <img
              src={iconUrl || 'https://via.placeholder.com/64'}
              alt="Section icon"
              loading="lazy"
              className="w-10 h-10 object-cover rounded-md border border-gray-200"
            />
          ) : (
            <div className="w-10 h-10 rounded-md bg-blue-50 border border-blue-100 flex items-center justify-center">
              <span className="text-blue-600">📚</span>
            </div>
          )}
        </div>
        <div className="flex-1">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-semibold text-gray-900">{titleLabel}</h3>
            <span className="px-2 py-0.5 text-xs font-medium rounded bg-blue-50 text-blue-700 border border-blue-100">
              {safeEntries.length.toLocaleString()} total
            </span>
          </div>
          {updatedLabel ? (
            <div className="mt-1 text-xs text-gray-500">Updated {updatedLabel}</div>
          ) : null}
        </div>
      </div>

      {displayed.length === 0 ? (
        <div className="p-4 bg-gray-50 rounded-md border border-dashed border-gray-200 text-center">
          <div className="text-2xl mb-1">🗓️</div>
          <div className="text-sm text-gray-600">No assignments to display</div>
        </div>
      ) : (
        <div className="space-y-2">
          {displayed.map((item, index) => (
            <div key={index} className="p-3 bg-gray-50 rounded-md border border-gray-200">
              <div className="flex items-start">
                <div className="mt-0.5 mr-2 text-green-600">•</div>
                <div className="flex-1">
                  <div className="text-sm text-gray-900">{typeof item === 'string' ? item : String(item)}</div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {remaining > 0 ? (
        <div className="mt-3 text-xs text-gray-500">
          And {remaining.toLocaleString()} more not shown
        </div>
      ) : null}
    </div>
  );
};
